//! sqlx `SqlitePool`, PRAGMA setup (design §15.2), `sqlx::migrate!` embedding,
//! and the repo CRUD layer (thin wrappers over **compile-time-checked** sqlx
//! `query!`/`query_as!` macros).
//!
//! ## Compile-time SQL validation
//!
//! Every query in this module uses `sqlx::query!` / `sqlx::query_as!`, which
//! validate the SQL text, column names, column types, and bind-parameter types
//! against the committed `.sqlx/` offline cache at **compile time**. This
//! catches schema drift before the code can even build.
//!
//! The `.sqlx/` cache is generated by `cargo sqlx prepare` against a fully
//! migrated reference database (see the project README / CI). CI sets
//! `SQLX_OFFLINE=true` so no live `DATABASE_URL` is needed during builds.
//!
//! Repo functions map the SQLite `INTEGER` columns onto `i64` in the row
//! structs (sqlx decodes `INTEGER` → `i64`) and cast to the idiomatic `i32` /
//! `bool` used by [`hydra_core::model`] at the boundary.

use std::str::FromStr;
use std::time::Duration;

use sqlx::migrate::MigrateError;
use sqlx::sqlite::{SqliteConnectOptions, SqliteJournalMode, SqlitePoolOptions, SqliteSynchronous};
use sqlx::SqlitePool;

use hydra_core::model::{
    LimitRole, Provider, ProviderKey, ProviderKeyBinding, ProviderModel, Tenant, TenantModel,
    TenantProvider,
};

use crate::crypto::{self, CryptoError, KeyProvider, Sealed};

// ---------------------------------------------------------------------------
// Pool initialisation + PRAGMAs (design §15.2)
// ---------------------------------------------------------------------------

/// Connect a `SqlitePool` and apply the production PRAGMAs (design §15.2):
/// `journal_mode=WAL`, `synchronous=NORMAL`, `busy_timeout=5000`,
/// `foreign_keys=ON`, `mmap_size=134217728`.
///
/// PRAGMAs are applied **per connection** via [`SqliteConnectOptions`]:
/// `foreign_keys` is connection-scoped in SQLite, so a one-shot
/// `PRAGMA foreign_keys=ON` on a single connection would not propagate to the
/// rest of the pool — the connect-options builder applies it to every fresh
/// connection, which is the root-cause-correct approach for a multi-connection
/// file-backed production pool.
///
/// For `:memory:` URLs the pool is pinned to a single connection: each
/// in-memory connection is otherwise an isolated empty database, so a pool
/// with more than one connection would make migrations invisible to other
/// connections (the canonical sqlx in-memory test pattern).
pub async fn init_pool(url: &str) -> Result<SqlitePool, sqlx::Error> {
    let opts = SqliteConnectOptions::from_str(url)?
        .journal_mode(SqliteJournalMode::Wal)
        .synchronous(SqliteSynchronous::Normal)
        .busy_timeout(Duration::from_millis(5000))
        .foreign_keys(true)
        .pragma("mmap_size", "134217728");

    let is_memory = url.contains(":memory:");
    let pool = SqlitePoolOptions::new()
        .max_connections(if is_memory { 1 } else { 8 })
        .connect_with(opts)
        .await?;
    Ok(pool)
}

/// Run the embedded migrations (`sqlx::migrate!("./migrations")`).
pub async fn run_migrate(pool: &SqlitePool) -> Result<(), MigrateError> {
    sqlx::migrate!("./migrations").run(pool).await
}

// ---------------------------------------------------------------------------
// Row structs (mirror SQLite types) + conversions to core entities.
// ---------------------------------------------------------------------------

#[derive(sqlx::FromRow, Debug, Clone)]
struct ProviderRow {
    id: String,
    key: String,
    name: String,
    endpoint: String,
    weight: i64,
    created_at: String,
    updated_at: String,
    /// Per-provider concurrency admission policy (design-admission-queue §5).
    /// Nullable: NULL ⇒ use ProxyConfig defaults (opt-in). SQLite INTEGER → i64.
    max_concurrency: Option<i64>,
    max_queue_depth: Option<i64>,
    queue_wait_timeout_ms: Option<i64>,
}

/// Cast a nullable SQLite INTEGER (decoded as `Option<i64>`) to `Option<u32>`,
/// rejecting negative values (defensive — a manual DB edit should not panic the
/// loader). Negative ⇒ `None` (treated as "use defaults").
fn to_u32_opt(v: Option<i64>) -> Option<u32> {
    v.filter(|n| *n >= 0).map(|n| n as u32)
}

/// Same as [`to_u32_opt`] but for `u64` (`queue_wait_timeout_ms`).
fn to_u64_opt(v: Option<i64>) -> Option<u64> {
    v.filter(|n| *n >= 0).map(|n| n as u64)
}

impl From<ProviderRow> for Provider {
    fn from(r: ProviderRow) -> Self {
        Provider {
            id: r.id,
            key: r.key,
            name: r.name,
            endpoint: r.endpoint,
            weight: r.weight as i32,
            created_at: r.created_at,
            updated_at: r.updated_at,
            max_concurrency: to_u32_opt(r.max_concurrency),
            max_queue_depth: to_u32_opt(r.max_queue_depth),
            queue_wait_timeout_ms: to_u64_opt(r.queue_wait_timeout_ms),
        }
    }
}

