pub async fn insert_limit_role(pool: &SqlitePool, r: &LimitRole) -> Result<(), sqlx::Error> {
    sqlx::query!(
        "INSERT INTO limit_role (id, name, matching_key, matching_model, matching_tenant, \
         matching_provider, limit_count, limit_token, window, enabled, created_at) \
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        r.id,
        r.name,
        r.matching_key,
        r.matching_model,
        r.matching_tenant,
        r.matching_provider,
        r.limit_count,
        r.limit_token,
        r.window,
        r.enabled,
        r.created_at,
    )
    .execute(pool)
    .await?;
    Ok(())
}

pub async fn get_limit_role(pool: &SqlitePool, id: &str) -> Result<LimitRole, sqlx::Error> {
    let row = sqlx::query_as!(
        LimitRoleRow,
        r#"SELECT id as "id!", name, matching_key, matching_model, matching_tenant,
                  matching_provider, limit_count, limit_token, window, enabled, created_at
           FROM limit_role WHERE id = ?"#,
        id
    )
    .fetch_one(pool)
    .await?;
    Ok(row.into())
}

pub async fn list_limit_roles(pool: &SqlitePool) -> Result<Vec<LimitRole>, sqlx::Error> {
    let rows = sqlx::query_as!(
        LimitRoleRow,
        r#"SELECT id as "id!", name, matching_key, matching_model, matching_tenant,
                  matching_provider, limit_count, limit_token, window, enabled, created_at
           FROM limit_role ORDER BY created_at"#
    )
    .fetch_all(pool)
    .await?;
    Ok(rows.into_iter().map(Into::into).collect())
}

/// Update a limit role's mutable fields.
pub async fn update_limit_role(pool: &SqlitePool, r: &LimitRole) -> Result<(), sqlx::Error> {
    sqlx::query!(
        "UPDATE limit_role SET name = ?, matching_key = ?, matching_model = ?, \
         matching_tenant = ?, matching_provider = ?, limit_count = ?, limit_token = ?, \
         window = ?, enabled = ? WHERE id = ?",
        r.name,
        r.matching_key,
        r.matching_model,
        r.matching_tenant,
        r.matching_provider,
        r.limit_count,
        r.limit_token,
        r.window,
        r.enabled,
        r.id,
    )
    .execute(pool)
    .await?;
    Ok(())
}

pub async fn delete_limit_role(pool: &SqlitePool, id: &str) -> Result<(), sqlx::Error> {
    sqlx::query!("DELETE FROM limit_role WHERE id = ?", id)
        .execute(pool)
        .await?;
    Ok(())
}

// ---------------------------------------------------------------------------
// CRUD — provider_key_binding (design §7.1b)
// ---------------------------------------------------------------------------

/// Insert a binding. Violating the UNIQUE `key_prefix` constraint returns a
/// sqlx UNIQUE violation (→ 409 by the admin layer).
pub async fn insert_provider_key_binding(
    pool: &SqlitePool,
    b: &ProviderKeyBinding,
) -> Result<(), sqlx::Error> {
    sqlx::query!(
        "INSERT INTO provider_key_binding (id, key_prefix, provider_id, enabled, created_at, \
         updated_at) VALUES (?, ?, ?, ?, ?, ?)",
        b.id,
        b.key_prefix,
        b.provider_id,
        b.enabled,
        b.created_at,
        b.updated_at
    )
    .execute(pool)
    .await?;
    Ok(())
}

pub async fn get_provider_key_binding(
    pool: &SqlitePool,
    id: &str,
) -> Result<ProviderKeyBinding, sqlx::Error> {
    let row = sqlx::query_as!(
        ProviderKeyBindingRow,
        r#"SELECT id as "id!", key_prefix, provider_id, enabled, created_at, updated_at
           FROM provider_key_binding WHERE id = ?"#,
        id
    )
    .fetch_one(pool)
    .await?;
    Ok(row.into())
}

pub async fn list_provider_key_bindings(
    pool: &SqlitePool,
) -> Result<Vec<ProviderKeyBinding>, sqlx::Error> {
    let rows = sqlx::query_as!(
        ProviderKeyBindingRow,
        r#"SELECT id as "id!", key_prefix, provider_id, enabled, created_at, updated_at
           FROM provider_key_binding ORDER BY key_prefix"#
    )
    .fetch_all(pool)
    .await?;
    Ok(rows.into_iter().map(Into::into).collect())
}

/// Update a binding's mutable fields (prefix / provider / enabled).
pub async fn update_provider_key_binding(
    pool: &SqlitePool,
    b: &ProviderKeyBinding,
) -> Result<(), sqlx::Error> {
    sqlx::query!(
        "UPDATE provider_key_binding SET key_prefix = ?, provider_id = ?, enabled = ?, \
         updated_at = ? WHERE id = ?",
        b.key_prefix,
        b.provider_id,
        b.enabled,
        b.updated_at,
        b.id
    )
    .execute(pool)
    .await?;
    Ok(())
}

pub async fn delete_provider_key_binding(pool: &SqlitePool, id: &str) -> Result<(), sqlx::Error> {
    sqlx::query!("DELETE FROM provider_key_binding WHERE id = ?", id)
        .execute(pool)
        .await?;
    Ok(())
}
